// Simplified Inversify-like implementation
class Container {
  constructor() {
    this.bindings = new Map();
    this.singletons = new Map();
  }

  bind(token) {
    return {
      to: (constructor) => {
        this.bindings.set(token, { type: 'transient', constructor });
        return this;
      },
      toSelf: () => {
        // Assume token IS the constructor
        this.bindings.set(token, { type: 'transient', constructor: token });
        return this;
      },
      toConstantValue: (value) => {
        this.bindings.set(token, { type: 'constant', value });
        return this;
      },
      inSingletonScope: () => {
        const binding = this.bindings.get(token);
        if (binding) binding.type = 'singleton';
        return this;
      }
    };
  }

  get(token) {
    const binding = this.bindings.get(token);
    if (!binding) throw new Error('No binding found for token: ' + token);

    if (binding.type === 'constant') {
      return binding.value;
    }

    if (binding.type === 'singleton') {
      if (!this.singletons.has(token)) {
        this.singletons.set(token, this.createInstance(binding.constructor));
      }
      return this.singletons.get(token);
    }

    return this.createInstance(binding.constructor);
  }

  createInstance(constructor) {
    // Get constructor parameters
    const paramTypes = constructor.__inject || [];
    const args = paramTypes.map(token => this.get(token));
    return new constructor(...args);
  }
}

function injectable() {
  return function(target) {
    target.__injectable = true;
    return target;
  };
}

function inject(token) {
  return function(target, propertyKey, parameterIndex) {
    if (!target.__inject) target.__inject = [];
    target.__inject[parameterIndex] = token;
  };
}

// === TOKENS ===
const TYPES = {
  Database: Symbol('Database'),
  Logger: Symbol('Logger'),
  OrderRepository: Symbol('OrderRepository'),
  OrderService: Symbol('OrderService'),
  OrderController: Symbol('OrderController')
};

// === IMPLEMENTATIONS ===

@injectable()
class ConsoleLogger {
  log(message) {
    console.log('[LOG]', message);
  }
}

@injectable()
class InMemoryDatabase {
  constructor() {
    this.data = new Map();
  }

  save(collection, id, data) {
    if (!this.data.has(collection)) this.data.set(collection, new Map());
    this.data.get(collection).set(id, data);
  }

  find(collection, id) {
    return this.data.get(collection)?.get(id);
  }
}

@injectable()
class OrderRepository {
  constructor(@inject(TYPES.Database) db, @inject(TYPES.Logger) logger) {
    this.db = db;
    this.logger = logger;
  }

  save(order) {
    this.logger.log('Saving order: ' + order.id);
    this.db.save('orders', order.id, order);
  }

  findById(id) {
    this.logger.log('Finding order: ' + id);
    return this.db.find('orders', id);
  }
}

@injectable()
class OrderService {
  constructor(@inject(TYPES.OrderRepository) repository) {
    this.repository = repository;
  }

  createOrder(orderData) {
    const order = { id: Date.now(), ...orderData, status: 'created' };
    this.repository.save(order);
    return order;
  }
}

@injectable()
class OrderController {
  constructor(@inject(TYPES.OrderService) service) {
    this.service = service;
  }

  create(req) {
    return this.service.createOrder(req.body);
  }
}

// === COMPOSITION ROOT ===
const container = new Container();

container.bind(TYPES.Logger).to(ConsoleLogger).inSingletonScope();
container.bind(TYPES.Database).to(InMemoryDatabase).inSingletonScope();
container.bind(TYPES.OrderRepository).to(OrderRepository);
container.bind(TYPES.OrderService).to(OrderService);
container.bind(TYPES.OrderController).to(OrderController);

// === USAGE ===
const controller = container.get(TYPES.OrderController);

console.log('InversifyJS Dependency Injection Example');
console.log('');
console.log('Container bindings:');
console.log('  Logger (singleton)        -> ConsoleLogger');
console.log('  Database (singleton)      -> InMemoryDatabase');
console.log('  OrderRepository           -> OrderRepository');
console.log('  OrderService              -> OrderService');
console.log('  OrderController           -> OrderController');
console.log('');
console.log('Dependency chain:');
console.log('  OrderController -> OrderService -> OrderRepository -> [Database, Logger]');
console.log('');

const order = controller.create({ body: { customerId: 1, items: ['book'], total: 29.99 } });
console.log('Created order:', order);
